INSERT INTO libros (titulo, autor, genero, anio_publicacion, estado, sinopsis, portada) VALUES
('Dune', 'Frank Herbert', 'Ciencia ficción', 1965, 'leido', 'En el desértico planeta Arrakis, la única fuente de la especia más valiosa del universo, la familia Atreides recibe el gobierno del planeta en una trampa tendida por sus enemigos. Tras la traición, el joven Paul Atreides huye al desierto y encuentra refugio entre los fremen, el pueblo nativo, donde empieza a forjarse un destino que cambiará el imperio.', 'dune_portada.webp'),
('El nombre del viento', 'Patrick Rothfuss', 'Fantasía', 2007, 'leyendo', 'Desde una posada perdida en un pueblo tranquilo, Kvothe, un hombre convertido en leyenda, decide contar por fin su verdadera historia. Su relato recorre su infancia en una compañía de artistas ambulantes, la tragedia que lo dejó solo y sus años en la Universidad, donde estudia arcanismo mientras busca respuestas sobre los misteriosos Chandrian.', 'nombre_viento_portada.webp'),
('Don Quijote de la Mancha', 'Miguel de Cervantes', 'Clásico', 1605, 'leido', 'Un hidalgo manchego, trastornado por la lectura de novelas de caballerías, decide convertirse en caballero andante y sale a los caminos junto a su fiel escudero Sancho Panza. Entre molinos que confunde con gigantes y aventuras disparatadas, la novela mezcla humor y reflexión sobre la realidad, la locura y los ideales.', 'don_quijote_portada.webp'),
('Frankenstein', 'Mary Shelley', 'Terror', 1818, 'leyendo', 'El joven científico Victor Frankenstein consigue dar vida a un ser creado a partir de restos humanos, pero huye horrorizado de su propia obra. Abandonada y rechazada por todos, la criatura busca su lugar en el mundo, y el enfrentamiento entre creador y criatura desata una tragedia que los perseguirá hasta los confines del mundo.', 'frankenstein_portada.webp'),
('Orgullo y prejuicio', 'Jane Austen', 'Romance', 1813, 'pendiente', 'En la Inglaterra rural de principios del siglo XIX, Elizabeth Bennet, ingeniosa e independiente, choca una y otra vez con el orgulloso y reservado señor Darcy. Entre bailes, malentendidos y presiones familiares para casar a las cinco hermanas Bennet, ambos descubrirán que las primeras impresiones pueden engañar.', 'orgullo_prejuicio_portada.webp'),
('1984', 'George Orwell', 'Ciencia ficción', 1949, 'leido', 'Winston Smith trabaja en el Ministerio de la Verdad reescribiendo la historia para el Partido, en un Estado donde el Gran Hermano lo vigila todo. Cuando empieza a dudar del sistema y se enamora de Julia, descubre lo caro que se paga atreverse a pensar por uno mismo.', '1984_portada.webp'),
('Cien años de soledad', 'Gabriel García Márquez', 'Fantasía', 1967, 'pendiente', 'La novela narra la historia de la familia Buendía a lo largo de siete generaciones en el pueblo de Macondo, desde su fundación hasta su final. En sus páginas lo extraordinario convive con lo cotidiano, y los nombres, las pasiones y los errores de la familia parecen repetirse una y otra vez.', 'cien_anos_soledad_portada.webp'),
('El Hobbit', 'J.R.R. Tolkien', 'Fantasía', 1937, 'leyendo', 'Bilbo Bolsón, un hobbit amante de la tranquilidad y de su cómoda casa, se ve arrastrado por el mago Gandalf y trece enanos a una gran aventura. Su objetivo es recuperar el tesoro custodiado por el dragón Smaug en la Montaña Solitaria, y por el camino Bilbo descubrirá un valor que no sabía que tenía.', 'el_hobbit_portada.webp'),
('Drácula', 'Bram Stoker', 'Terror', 1897, 'leido', 'El joven abogado Jonathan Harker viaja a Transilvania para cerrar la compra de una casa en Londres con el misterioso conde Drácula, y pronto descubre que es prisionero en su castillo. Cuando el conde llega a Inglaterra, el doctor Van Helsing y un pequeño grupo de amigos se unen para detenerlo. La historia se cuenta a través de diarios y cartas de los protagonistas.', 'dracula_portada.webp'),
('El Principito', 'Antoine de Saint-Exupéry', 'Clásico', 1943, 'leido', 'Un aviador sufre una avería en pleno desierto del Sahara y allí conoce a un niño que dice venir de un pequeño asteroide. A medida que el principito le cuenta sus viajes por otros planetas y su relación con una rosa, el aviador recupera una forma de mirar el mundo que había olvidado al hacerse mayor.', 'principito_portada.webp'),
('Estudio en escarlata', 'Arthur Conan Doyle', 'Misterio', 1887, 'pendiente', 'El doctor Watson vuelve herido de la guerra y acaba compartiendo piso en Baker Street con Sherlock Holmes, un detective tan brillante como excéntrico. Su primer caso juntos empieza con un cadáver en una casa vacía y una palabra escrita con sangre en la pared. Es la novela en la que aparecen por primera vez los dos personajes.', 'estudio_escarlata_portada.webp'),
('La sombra del viento', 'Carlos Ruiz Zafón', 'Misterio', 2001, 'leyendo', 'En la Barcelona de la posguerra, Daniel Sempere visita con su padre el Cementerio de los Libros Olvidados y se lleva un ejemplar de una novela de Julián Carax. Al intentar saber más del autor descubre que alguien lleva años quemando todos sus libros, y la búsqueda le arrastra a una historia de amores prohibidos y secretos de familia.', 'sombra_viento_portada.webp'),
('Fahrenheit 451', 'Ray Bradbury', 'Ciencia ficción', 1953, 'leido', 'En un futuro donde los libros están prohibidos, los bomberos no apagan incendios sino que queman cualquier obra que encuentren. Guy Montag es uno de ellos y nunca se ha cuestionado su trabajo, hasta que una joven vecina y una mujer que prefiere arder antes que separarse de sus libros le hacen preguntarse qué está destruyendo.', 'fahrenheit_451_portada.webp'),
('El retrato de Dorian Gray', 'Oscar Wilde', 'Clásico', 1890, 'pendiente', 'Dorian Gray es un joven de belleza extraordinaria que, al ver el retrato que le ha pintado su amigo Basil, desea que sea el cuadro el que envejezca en su lugar. El deseo se cumple: Dorian se mantiene joven mientras se entrega a una vida cada vez más oscura, y es el retrato, escondido bajo llave, el que va mostrando cada una de sus faltas.', 'dorian_gray_portada.webp'),
('La isla del tesoro', 'Robert Louis Stevenson', 'Aventura', 1883, 'pendiente', 'Jim Hawkins, hijo de los dueños de una posada, encuentra entre las cosas de un viejo marinero el mapa de una isla donde un pirata enterró su tesoro. Jim se embarca en la Hispaniola, pero parte de la tripulación son piratas a las órdenes del cocinero Long John Silver, que también quiere el botín.', 'isla_tesoro_portada.webp'),
('Rimas y leyendas', 'Gustavo Adolfo Bécquer', 'Poesía', 1871, 'leyendo', 'Reúne los breves poemas de Bécquer sobre el amor, la poesía y el desengaño junto a sus leyendas en prosa, relatos de ambiente medieval y misterioso situados en lugares como Soria o Toledo. Es una de las obras más leídas del Romanticismo español y se publicó por primera vez tras la muerte del autor.', 'rimas_leyendas_portada.webp');
INSERT INTO resenas (id_libro, lector_nombre, puntuacion, comentario) VALUES
(1, 'Elena G.', 5, 'Obra maestra absoluta de la ciencia ficción. Imprescindible.'),
(2, 'Marcos R.', 4, 'La forma de narrar de Kvothe engancha desde la primera página. Se hace algo lento en la parte central, pero merece la pena.'),
(3, 'Lucía P.', 5, 'Mucho más divertido de lo que esperaba. Sancho Panza es uno de los mejores personajes que he leído nunca.'),
(4, 'Andrés M.', 4, 'Nada que ver con las películas: es una historia triste sobre la soledad y la responsabilidad. Muy recomendable.'),
(6, 'Carmen V.', 5, 'Inquietante y cada vez más actual. Al terminarlo no puedes dejar de pensar en él durante días.'),
(6, 'Javier L.', 3, 'La idea es brillante, pero el ritmo de la última parte me resultó pesado.'),
(8, 'Sara T.', 5, 'Perfecto para empezar con la fantasía. Tiene humor, aventura y un dragón inolvidable.');